"""Durable-state verification for the Android OpenNote tasks.

OpenNote keeps its whole working state in one JSON document in the WebView's
``localStorage``: the signed-in session, the user directory, the note feed, the
comments recorded against each note, the per-account record of what that account
liked and saved, and an ordered log of the actions the application recorded.

A judgement reads that document and compares it against the outcome the
instruction asks for.  Only outcomes are compared: which sheet was open, how far
a list was scrolled and which control was pressed leave no durable record and are
not judged.  What is compared is exact -- titles and bodies character for
character, category and location as written, tags as an ordered set, and the
per-account liked/saved membership as a set.
"""

from __future__ import annotations

import hashlib
import json
import re
from typing import Any, Mapping, Sequence

from evaluators.cua_review.core.evaluation import BaseEvaluator, EvalResult, EvalStatus
