#: Application identifier of OpenNote on the device.
DEFAULT_APP_PACKAGE = "com.killt.opennote"

#: ``localStorage`` key holding the OpenNote state document.
LOCAL_STATE_KEY = "opennote.localState.v2"


def items(state: Mapping[str, Any] | None, key: str) -> list[dict[str, Any]]:
    """Return one collection of a state document as a list of records."""
    if not isinstance(state, Mapping):
        return []
    value = state.get(key)
    if isinstance(value, list):
        return [dict(item) for item in value if isinstance(item, Mapping)]
    return []


def session_user(state: Mapping[str, Any] | None) -> dict[str, Any]:
    """Return the signed-in user recorded by a state document."""
    if not isinstance(state, Mapping):
        return {}
    session = state.get("session")
    if not isinstance(session, Mapping):
        return {}
    user = session.get("user")
    return dict(user) if isinstance(user, Mapping) else {}


def account_record(state: Mapping[str, Any] | None, handle: str) -> dict[str, Any]:
    """Return the per-account record for *handle*, whichever layout holds it.

    The document has carried the per-account record both directly under
    ``userState`` and under ``userStateByHandle`` keyed by handle; both shapes
    describe the same record, so both are read.
    """
    if not isinstance(state, Mapping):
        return {}
    by_handle = state.get("userStateByHandle")
    if isinstance(by_handle, Mapping):
        record = by_handle.get(str(handle))
        if isinstance(record, Mapping):
            return dict(record)
    user_state = state.get("userState")
    if isinstance(user_state, Mapping):
        record = user_state.get(str(handle))
        if isinstance(record, Mapping):
            return dict(record)
        if "likedNoteIds" in user_state or "savedNoteIds" in user_state:
            return dict(user_state)
    return {}


def id_set(record: Mapping[str, Any], key: str) -> set[str]:
    """Return one identifier collection of an account record as a set."""
    value = record.get(key) if isinstance(record, Mapping) else None
    return {str(item) for item in value} if isinstance(value, list) else set()


def unique(records: Sequence[Mapping[str, Any]], **fields: Any) -> tuple[dict[str, Any] | None, int]:
    """Return the single record matching every field, and how many matched."""
    found = [
        dict(record)
        for record in records
        if all(record.get(key) == value for key, value in fields.items())
    ]
    return (found[0] if len(found) == 1 else None), len(found)


def comments_for(state: Mapping[str, Any] | None, note_id: str) -> list[dict[str, Any]]:
    """Return the comments recorded against one note.

    A comment may be authored by the account itself or by another account; the
    caller decides what it is looking for.
    """
    if not isinstance(state, Mapping):
        return []
    comments = state.get("comments")
    if not isinstance(comments, Mapping):
        return []
    value = comments.get(str(note_id))
    if isinstance(value, list):
        return [dict(item) for item in value if isinstance(item, Mapping)]
    if isinstance(value, Mapping):
        return [dict(value)]
    return []


def comment_text(comment: Mapping[str, Any]) -> str:
    """Return a comment's text, whichever field carries it."""
    for key in ("text", "body", "content", "comment"):
        value = comment.get(key)
        if isinstance(value, str) and value.strip():
            return value
    return ""


def comment_author(comment: Mapping[str, Any]) -> str:
    """Return a comment's author handle, whichever field carries it."""
    for key in ("authorHandle", "handle", "author"):
        value = comment.get(key)
        if isinstance(value, str) and value.strip():
            return value
    author = comment.get("user")
    if isinstance(author, Mapping):
        return str(author.get("handle") or "")
    return ""


def ruleset_digest(spec: Mapping[str, Any]) -> str:
    """Return the digest of a ruleset, computed the same way everywhere."""
    return hashlib.sha256(
        json.dumps(
            spec, ensure_ascii=False, sort_keys=True, separators=(",", ":")
        ).encode("utf-8")
    ).hexdigest()


def json_safe(value: Any) -> Any:
    """Convert a value into something a JSON writer accepts."""
    if isinstance(value, Mapping):
        return {str(key): json_safe(item) for key, item in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [json_safe(item) for item in value]
    return value


def _installed_note_tags(values: Sequence[Any] | None) -> list[str]:
    """Return tag tokens the way the installed APK parses tag text.

    ``local-api.js`` in the installed APK splits the typed tag text on
    ``/[,#\\s]+/`` and keeps the first five tokens, so a tag written as
    ``"lunch route"`` is persisted as ``["lunch", "route"]``.  The same parser
    is documented by the repository's compatibility wrapper at
    ``local_eval/opennote_evaluator.py:10-11``.  Multiplicity and order are
    preserved -- this is an ordered token list, not a set.
    """
    tags: list[str] = []
    for value in values or []:
        tags.extend(
            token.strip()
            for token in re.split(r"[,#\s]+", str(value))
            if token.strip()
        )
    return tags[:5]


def check(
    name: str,
    passed: bool,
    expected: Any = None,
    observed: Any = None,
    *,
    steps: Sequence[int] = (),
    evidence: Any = None,
) -> dict[str, Any]:
    """Build one check record in the shape the recorded runs carry."""
    return {
        "name": name,
        "steps": list(steps),
        "passed": bool(passed),
        "expected": json_safe(expected),
        "observed": json_safe(observed),
        "evidence": json_safe(evidence),
        "failure_reason": None
        if passed
        else "exact value, cardinality, or membership mismatch",
    }


class OpenNoteAndroidEvaluator(BaseEvaluator):
    """Base class for the Android OpenNote tasks.

    Subclasses supply :data:`RULESET_SPEC`, whose ``expected`` entry states the
    outcome the instruction asks for: the account that must be signed in, the
    profile role, the notes that must be engaged with, and the notes that must
    have been published with their exact fields.
    """

    #: The criteria this evaluator implements.
    RULESET_SPEC: Mapping[str, Any] = {}

    #: Digest of :attr:`RULESET_SPEC`, used to bind the evaluator to its task.
    RULESET_SHA256 = ""

    #: Instruction digest the criteria were derived from.
    INSTRUCTION_SHA256 = ""

    @classmethod
    def ruleset_digest(cls) -> str:
        """Return the digest of the criteria this evaluator implements."""
        return ruleset_digest(cls.RULESET_SPEC)

    # ------------------------------------------------------------ judgement
    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        controller = context.get("controller")
        params = dict(context.get("params") or {})
        if controller is None or not hasattr(controller, "execute_adb"):
            return EvalResult(
                status=EvalStatus.ERROR,
                message="runner-provided controller.execute_adb is required",
                metadata={"read_only": True},
            )

        declared = str(params.get("expected_ruleset_sha256") or "").strip()
        if declared and self.RULESET_SHA256 and declared != self.RULESET_SHA256:
            return EvalResult(
                status=EvalStatus.ERROR,
                message="the task is bound to a different OpenNote ruleset",
                metadata={
                    "read_only": True,
                    "expected_ruleset_sha256": declared,
                    "evaluator_ruleset_sha256": self.RULESET_SHA256,
                },
            )

        try:
            state = WebViewDevTools(
                controller,
                str(params.get("app_package") or DEFAULT_APP_PACKAGE),
            ).read_key_as_document(
                str(params.get("local_state_key") or LOCAL_STATE_KEY)
            )
        except Exception as exc:  # noqa: BLE001
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"Failed to read OpenNote state: {type(exc).__name__}: {exc}",
                metadata={
                    "read_only": True,
                    "app_package": str(params.get("app_package") or DEFAULT_APP_PACKAGE),
                    "local_state_key": str(params.get("local_state_key") or LOCAL_STATE_KEY),
                    "exception_type": type(exc).__name__,
                },
            )

        checks = self.compare(state, self.RULESET_SPEC.get("expected") or {})
        failures = [entry["name"] for entry in checks if not entry["passed"]]
        metadata = {
            "read_only": True,
            "task_id": str(context.get("task_id") or ""),
            "ruleset_sha256": self.RULESET_SHA256,
            "ruleset_spec": json_safe(self.RULESET_SPEC),
            "checks": checks,
            "failures": failures,
            "state_summary": {
                "notes": len(items(state, "notes")),
                "users": len(items(state, "users")),
                "evaluationEvents": len(items(state, "evaluationEvents")),
            },
        }
        if failures:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenNote durable state does not match the requested outcome",
                metadata=metadata,
            )
        return EvalResult(
            status=EvalStatus.PASS,
            message="OpenNote durable state matches the requested outcome",
            metadata=metadata,
        )

    # ----------------------------------------------------------- comparison
    def compare(
        self, state: Mapping[str, Any], expected: Mapping[str, Any]
    ) -> list[dict[str, Any]]:
        """Compare the requested outcome against the application's state."""
        checks: list[dict[str, Any]] = []
        handle = str(expected.get("handle") or "")

        session = state.get("session") if isinstance(state.get("session"), Mapping) else {}
        user = session_user(state)
        observed_handle = str(user.get("handle") or "")
        checks.append(
            check(
                "session_signed_in",
                bool(session.get("loggedIn")) is True,
                True,
                bool(session.get("loggedIn")),
                steps=expected.get("login_steps", ()),
            )
        )
        checks.append(
            check(
                "session_handle_exact",
                bool(handle) and observed_handle == handle,
                handle,
                observed_handle,
                steps=expected.get("login_steps", ()),
            )
        )

        role = str(expected.get("profile_role") or "")
        if role:
            profile, profile_count = unique(items(state, "users"), handle=handle)
            observed_role = str((profile or {}).get("title") or "")
            checks.append(
                check(
                    "profile_role_exact",
                    profile_count == 1 and observed_role == role,
                    {"match_count": 1, "title": role},
                    {"match_count": profile_count, "title": observed_role},
                    steps=expected.get("profile_steps", ()),
                )
            )

        account = account_record(state, handle)
        liked = id_set(account, "likedNoteIds")
        saved = id_set(account, "savedNoteIds")
        notes = items(state, "notes")

        for spec in expected.get("notes", []):
            title = str(spec.get("title") or "")
            note, count = unique(notes, title=title)
            note_id = str((note or {}).get("id") or "")
            checks.append(
                check(
                    f"note_{title}_identity",
                    count == 1,
                    {"match_count": 1, "title": title},
                    {
                        "match_count": count,
                        "id": note_id,
                        "authorHandle": (note or {}).get("authorHandle"),
                    },
                    steps=spec.get("steps", ()),
                )
            )
            if spec.get("like"):
                checks.append(
                    check(
                        f"note_{title}_liked",
                        bool(note_id) and note_id in liked,
                        True,
                        bool(note_id) and note_id in liked,
                        steps=spec.get("steps", ()),
                    )
                )
            if spec.get("save"):
                checks.append(
                    check(
                        f"note_{title}_saved",
                        bool(note_id) and note_id in saved,
                        True,
                        bool(note_id) and note_id in saved,
                        steps=spec.get("steps", ()),
                    )
                )
            text = str(spec.get("comment") or "")
            if text:
                matches = [
                    entry
                    for entry in comments_for(state, note_id)
                    if comment_text(entry) == text and comment_author(entry) == handle
                ]
                checks.append(
                    check(
                        f"note_{title}_comment_exact",
                        bool(note_id) and len(matches) == 1,
                        {"text": text, "authorHandle": handle, "match_count": 1},
                        {
                            "match_count": len(matches),
                            "ids": [entry.get("id") for entry in matches],
                        },
                        steps=spec.get("steps", ()),
                    )
                )

        for spec in expected.get("created_notes", []):
            title = str(spec.get("title") or "")
            matches = [
                note
                for note in notes
                if note.get("title") == title and note.get("authorHandle") == handle
            ]
            note = matches[0] if len(matches) == 1 else {}
            observed_tags = (
                note.get("tags") if isinstance(note.get("tags"), list) else []
            )
            # Compare tags after the installed APK's parser: the app splits
            # tag text on /[,#\s]+/ and stores at most five tokens, so
            # "lunch route" is persisted as ["lunch", "route"].  Strings,
            # order and multiplicity stay exact; only the token boundary is
            # normalized.  See local_eval/opennote_evaluator.py:10-11.
            observed = {
                "title": note.get("title"),
                "text": note.get("text"),
                "category": note.get("category"),
                "location": note.get("location"),
                "tags": _installed_note_tags(observed_tags),
            }
            required = {
                "title": title,
                "text": str(spec.get("text") or ""),
                "category": str(spec.get("category") or ""),
                "location": str(spec.get("location") or ""),
                "tags": _installed_note_tags(spec.get("tags") or []),
            }
            checks.append(
                check(
                    f"created_note_{title}_exact",
                    len(matches) == 1 and observed == required,
                    {"match_count": 1, **required},
                    {"match_count": len(matches), **observed},
                    steps=spec.get("steps", ()),
                )
            )
            # The application records the creation of a note against the note
            # itself, so the record joins the note to the action that produced
            # it.  A note that no creation was recorded for was already there.
            note_id = str(note.get("id") or "")
            creations = [
                event
                for event in items(state, "evaluationEvents")
                if str(event.get("type") or "") == "note_created"
                and str(event.get("title") or "") == title
                and str(event.get("noteId") or note_id) == note_id
            ]
            checks.append(
                check(
                    f"created_note_{title}_recorded",
                    bool(note_id) and len(creations) >= 1,
                    {"title": title, "match_count": "at least one"},
                    {"note_id": note_id, "match_count": len(creations)},
                    steps=spec.get("steps", ()),
                )
            )

        return checks


